#[test]
fn kotlin_cross_file_branching_interface_chain_member_calls_fail_closed_for_unsupported_references()
{
    let dir = temporary_dir();
    let caller_path = dir.join("Caller.kt");
    let base_path = dir.join("Base.kt");
    let db_path = dir.join("symbols.db");
    fs::write(
        &caller_path,
        "package com.example\n\nimport org.util.A\nimport org.util.B\nimport org.util.BlockedMixed\nimport org.util.Competing\nimport org.util.Good\nimport org.util.X\nimport org.util.Y\n\nfun competingCaller(competing: Competing): Int = competing.helper(1)\n\nfun cyclicCaller(x: X): Int = x.helper(1)\n\nfun blockedCaller(blocked: BlockedMixed): Int = blocked.helper(1)\n\nfun control(good: Good): Int = good.render(1)\n",
    )
    .unwrap();
    fs::write(
        &base_path,
        "package org.util\n\ninterface A {\n    fun helper(value: Int): Int = value\n}\ninterface B {\n    fun helper(value: Int): Int = value\n}\ninterface Competing : A, B\ninterface X : Y\ninterface Y : X\ninterface Bad : Missing\ninterface BlockedMixed : A, Bad\ninterface Root {\n    fun render(value: Int): Int = value\n}\ninterface Good : Root\n",
    )
    .unwrap();

    // Competing declarations across branches, a cyclic interface chain, and
    // a branch with an unresolvable parent all fail closed; only the
    // uniquely resolvable inherited member in `control` traces.
    let helper_path = "org::util::A::helper";
    let live = trace_symbol_graph(&dir, helper_path, TraceDirection::Callers).unwrap();
    assert!(
        live.callers.is_empty(),
        "competing and blocked branches must fail closed"
    );

    let render_path = "org::util::Root::render";
    let live = trace_symbol_graph(&dir, render_path, TraceDirection::Callers).unwrap();
    assert_eq!(live.callers.len(), 1);
    assert_eq!(live.callers[0].symbol_id, "com::example::control");

    rebuild_symbol_index(&dir, &db_path).unwrap();
    let persisted =
        trace_symbol_graph_from_index(&db_path, helper_path, TraceDirection::Callers).unwrap();
    assert!(
        persisted.callers.is_empty(),
        "competing and blocked branches must fail closed"
    );
    let persisted =
        trace_symbol_graph_from_index(&db_path, render_path, TraceDirection::Callers).unwrap();
    assert_eq!(persisted.callers.len(), 1);
    assert_eq!(persisted.callers[0].symbol_id, "com::example::control");
}

