#[test]
fn kotlin_cross_file_class_receiver_diamond_interface_chain_member_calls_fail_closed_for_unsupported_references()
 {
    let dir = temporary_dir();
    let caller_path = dir.join("Caller.kt");
    let base_path = dir.join("Interfaces.kt");
    let db_path = dir.join("symbols.db");
    fs::write(
        &caller_path,
        "package com.example\n\nimport org.util.Root\n\ninterface A {\n    fun helper(value: Int): Int = value\n}\ninterface B {\n    fun helper(value: Int): Int = value\n}\ninterface CompetingIface : A, B\ninterface X : Y\ninterface Y : X\ninterface Bad : Missing\ninterface BlockedIface : A, Bad\ninterface Good : Root\n\nclass Competing : CompetingIface\nclass Cyclic : X\nclass Blocked : BlockedIface\nclass Control : Good\n\nfun competingCaller(competing: Competing): Int {\n    return competing.helper(1)\n}\n\nfun cyclicCaller(cyclic: Cyclic): Int {\n    return cyclic.helper(1)\n}\n\nfun blockedCaller(blocked: Blocked): Int {\n    return blocked.helper(1)\n}\n\nfun control(control: Control): Int {\n    return control.render(1)\n}\n",
    )
    .unwrap();
    fs::write(
        &base_path,
        "package org.util\n\ninterface Root {\n    fun render(value: Int): Int = value\n}\n",
    )
    .unwrap();

    // Competing declarations across a class's implemented interface branches,
    // a cyclic interface chain, and a branch with an unresolvable parent all
    // fail closed through the class receiver; only the uniquely resolvable
    // inherited interface member in `control` traces across packages.
    let helper_path = "com::example::A::helper";
    let live = trace_symbol_graph(&dir, helper_path, TraceDirection::Callers).unwrap();
    assert!(
        live.callers.is_empty(),
        "competing and blocked class-receiver interface branches must fail closed"
    );

    let render_path = "org::util::Root::render";
    let live = trace_symbol_graph(&dir, render_path, TraceDirection::Callers).unwrap();
    assert_eq!(live.callers.len(), 1);
    assert_eq!(live.callers[0].symbol_id, "com::example::control");

    rebuild_symbol_index(&dir, &db_path).unwrap();
    let persisted =
        trace_symbol_graph_from_index(&db_path, helper_path, TraceDirection::Callers).unwrap();
    assert!(
        persisted.callers.is_empty(),
        "competing and blocked class-receiver interface branches must fail closed"
    );
    let persisted =
        trace_symbol_graph_from_index(&db_path, render_path, TraceDirection::Callers).unwrap();
    assert_eq!(persisted.callers.len(), 1);
    assert_eq!(persisted.callers[0].symbol_id, "com::example::control");
}

#[test]
fn traces_kotlin_class_receiver_generic_superclass_member_calls_in_live_workspace_and_persisted_index()
 {
    let dir = temporary_dir();
    let source_path = dir.join("Callers.kt");
    let db_path = dir.join("symbols.db");
    fs::write(
        &source_path,
        "package com.example\n\nclass Entry {\n    fun helper(value: Int): Int = value\n}\nopen class Base<T> {\n    fun baseHelper(value: Int): Int = value\n    val entry: Entry = Entry()\n}\nclass Derived : Base<Entry>()\n\nfun memberCaller(derived: Derived): Int {\n    return derived.baseHelper(1)\n}\n\nfun hopCaller(derived: Derived): Int {\n    return derived.entry.helper(1)\n}\n",
    )
    .unwrap();

    // A generic superclass specifier such as `Base<Entry>()` normalizes to the
    // raw base type, so a class-typed receiver dispatches members declared on
    // the generic superclass and walks property hops through it.
    let base_helper_path = "com::example::Base::baseHelper";
    let live = trace_symbol_graph(&dir, base_helper_path, TraceDirection::Callers).unwrap();
    assert_eq!(live.symbol.symbol_id, base_helper_path);
    assert_eq!(live.callers.len(), 1);
    assert_eq!(live.callers[0].symbol_id, "com::example::memberCaller");

    let entry_helper_path = "com::example::Entry::helper";
    let live = trace_symbol_graph(&dir, entry_helper_path, TraceDirection::Callers).unwrap();
    assert_eq!(live.callers.len(), 1);
    assert_eq!(live.callers[0].symbol_id, "com::example::hopCaller");

    rebuild_symbol_index(&dir, &db_path).unwrap();
    let persisted =
        trace_symbol_graph_from_index(&db_path, base_helper_path, TraceDirection::Callers).unwrap();
    assert_eq!(persisted.callers.len(), 1);
    assert_eq!(persisted.callers[0].symbol_id, "com::example::memberCaller");
    let persisted =
        trace_symbol_graph_from_index(&db_path, entry_helper_path, TraceDirection::Callers)
            .unwrap();
    assert_eq!(persisted.callers.len(), 1);
    assert_eq!(persisted.callers[0].symbol_id, "com::example::hopCaller");
}

