#[test]
fn traces_kotlin_cross_file_explicit_companion_chain_member_calls_in_live_workspace_and_persisted_index()
 {
    let dir = temporary_dir();
    let caller_path = dir.join("Caller.kt");
    let base_path = dir.join("Config.kt");
    let db_path = dir.join("symbols.db");
    fs::write(
        &caller_path,
        "package com.example\n\nimport org.util.Config\n\nfun caller(): Int = Config.Companion.helper(1)\n\nfun secondCaller(): Int = Config.Companion.helper(2)\n",
    )
    .unwrap();
    fs::write(
        &base_path,
        "package org.util\n\nclass Config {\n    companion object {\n        fun helper(value: Int): Int = value\n    }\n}\n",
    )
    .unwrap();

    // An explicit companion chain such as `Config.Companion.helper(...)` where
    // the class is declared in an explicitly imported package dispatches
    // directly to the imported class's canonical companion member.
    let helper_path = "org::util::Config::Companion::helper";
    let live = trace_symbol_graph(&dir, helper_path, TraceDirection::Callers).unwrap();
    assert_eq!(live.indexed_files, 2);
    assert_eq!(live.symbol.symbol_id, helper_path);
    assert_eq!(live.callers.len(), 2);
    assert!(
        live.callers
            .iter()
            .any(|caller| caller.symbol_id == "com::example::caller")
    );
    assert!(
        live.callers
            .iter()
            .any(|caller| caller.symbol_id == "com::example::secondCaller")
    );

    rebuild_symbol_index(&dir, &db_path).unwrap();
    let persisted =
        trace_symbol_graph_from_index(&db_path, helper_path, TraceDirection::Callers).unwrap();
    assert_eq!(persisted.indexed_files, 2);
    assert_eq!(persisted.callers.len(), 2);
    assert!(
        persisted
            .callers
            .iter()
            .any(|caller| caller.symbol_id == "com::example::caller")
    );
    assert!(
        persisted
            .callers
            .iter()
            .any(|caller| caller.symbol_id == "com::example::secondCaller")
    );
}

