#[test]
fn traces_kotlin_cross_file_deep_constructor_chain_receiver_calls_in_live_workspace_and_persisted_index()
 {
    let dir = temporary_dir();
    let caller_path = dir.join("Caller.kt");
    let group_path = dir.join("Group.kt");
    let db_path = dir.join("symbols.db");
    fs::write(
        &caller_path,
        "package com.example\n\nimport org.util.Group\n\nfun caller(): Int {\n    return Group().mid.inner.helper(1)\n}\n\nfun secondCaller(): Int {\n    return Group().mid.inner.helper(2)\n}\n",
    )
    .unwrap();
    fs::write(
        &group_path,
        "package org.util\n\nclass Inner {\n    fun helper(value: Int): Int = value\n}\nclass Mid {\n    val inner: Inner = Inner()\n}\nclass Group {\n    val mid: Mid = Mid()\n}\n",
    )
    .unwrap();

    // A constructor-call receiver from an imported package followed by multiple
    // property hops resolves each intermediate property's declared type in the
    // declaring type's own package scope before dispatching the trailing member
    // across packages.
    let helper_path = "org::util::Inner::helper";
    let live = trace_symbol_graph(&dir, helper_path, TraceDirection::Callers).unwrap();
    assert_eq!(live.indexed_files, 2);
    assert_eq!(live.symbol.symbol_id, helper_path);
    assert_eq!(live.callers.len(), 2);
    assert!(
        live.callers
            .iter()
            .any(|caller| caller.symbol_id == "com::example::caller")
    );
    assert!(
        live.callers
            .iter()
            .any(|caller| caller.symbol_id == "com::example::secondCaller")
    );

    rebuild_symbol_index(&dir, &db_path).unwrap();
    let persisted =
        trace_symbol_graph_from_index(&db_path, helper_path, TraceDirection::Callers).unwrap();
    assert_eq!(persisted.indexed_files, 2);
    assert_eq!(persisted.callers.len(), 2);
    assert!(
        persisted
            .callers
            .iter()
            .any(|caller| caller.symbol_id == "com::example::caller")
    );
    assert!(
        persisted
            .callers
            .iter()
            .any(|caller| caller.symbol_id == "com::example::secondCaller")
    );
}

