#[test]
fn traces_kotlin_companion_chain_array_element_access_method_hop_receiver_calls_across_files() {
    let dir = temporary_dir();
    let caller_path = dir.join("Callers.kt");
    let base_path = dir.join("Types.kt");
    let db_path = dir.join("symbols.db");
    fs::write(
        &caller_path,
        "package com.example\n\nimport org.util.Config\nimport org.util.Outer\n\nfun caller(): Int {\n    return Config.Factory.groups[0].inner().helper(1)\n}\n\nfun nestedCaller(): Int {\n    return Outer.Inner.NestedFactory.groups[0].inner().helper(1)\n}\n",
    )
    .unwrap();
    fs::write(
        &base_path,
        "package org.util\n\nclass Item {\n    fun helper(value: Int): Int = value\n}\n\nclass Helper {\n    val item: Item = Item()\n    fun inner(): Item = item\n}\n\nclass Config {\n    companion object Factory {\n        val groups: Array<Helper> = arrayOf()\n    }\n}\n\nclass Outer {\n    class Inner {\n        companion object NestedFactory {\n            val groups: Array<Helper> = arrayOf()\n        }\n    }\n}\n",
    )
    .unwrap();

    // Companion-chain roots resolve across files through the same import
    // rules as other type receivers: `Config` and `Outer` resolve through the
    // explicit imports, the nested class `Outer.Inner` walks the nested type
    // declaration, and the array-property element-access plus method-call hops
    // dispatch on the imported package's declared types.
    let item_path = "org::util::Item::helper";
    let live = trace_symbol_graph(&dir, item_path, TraceDirection::Callers).unwrap();
    assert_eq!(live.indexed_files, 2);
    assert_eq!(live.symbol.symbol_id, item_path);
    assert_eq!(live.callers.len(), 2);
    for expected in ["com::example::caller", "com::example::nestedCaller"] {
        assert!(
            live.callers
                .iter()
                .any(|caller| caller.symbol_id == expected)
        );
    }

    rebuild_symbol_index(&dir, &db_path).unwrap();
    let persisted =
        trace_symbol_graph_from_index(&db_path, item_path, TraceDirection::Callers).unwrap();
    assert_eq!(persisted.indexed_files, 2);
    assert_eq!(persisted.callers.len(), 2);
    for expected in ["com::example::caller", "com::example::nestedCaller"] {
        assert!(
            persisted
                .callers
                .iter()
                .any(|caller| caller.symbol_id == expected)
        );
    }
}

#[test]
fn traces_kotlin_inline_anonymous_companion_array_element_access_receiver_calls_in_live_workspace_and_persisted_index()
 {
    let dir = temporary_dir();
    let source_path = dir.join("Callers.kt");
    let db_path = dir.join("symbols.db");
    fs::write(
        &source_path,
        "package com.example\n\nclass Item {\n    fun helper(value: Int): Int = value\n}\n\nclass Helper {\n    fun inner(): Item = Item()\n}\n\nclass Util {\n    companion object {\n        val items: Array<Item> = arrayOf()\n        val nullableItems: Array<Item>? = arrayOf()\n        val groups: Array<Helper> = arrayOf()\n        val nullableGroups: Array<Helper>? = arrayOf()\n    }\n}\n\nfun runPlain(): Int {\n    return Util.items[0].helper(1)\n}\n\nfun runNullableForce(): Int {\n    return Util.nullableItems!![0].helper(2)\n}\n\nfun runHop(): Int {\n    return Util.groups[0].inner().helper(3)\n}\n\nfun runNullableHop(): Int {\n    return Util.nullableGroups!![0].inner().helper(4)\n}\n",
    )
    .unwrap();

    // An inline element-access chain rooted at a class name whose terminal
    // array property lives on the class's anonymous companion object, such as
    // `Util.items[0].helper(...)`, dispatches on the declared element
    // component type; nullable array properties force-unwrap with `!!` the
    // same way, and a trailing method-call hop such as
    // `Util.groups[0].inner().helper(...)` continues on the element type.
    let item_path = "com::example::Item::helper";
    let live = trace_symbol_graph(&dir, item_path, TraceDirection::Callers).unwrap();
    assert_eq!(live.symbol.symbol_id, item_path);
    assert_eq!(live.callers.len(), 4);
    for caller in [
        "com::example::runPlain",
        "com::example::runNullableForce",
        "com::example::runHop",
        "com::example::runNullableHop",
    ] {
        assert!(
            live.callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing caller {caller}"
        );
    }

    rebuild_symbol_index(&dir, &db_path).unwrap();
    let persisted =
        trace_symbol_graph_from_index(&db_path, item_path, TraceDirection::Callers).unwrap();
    assert_eq!(persisted.callers.len(), 4);
    for caller in [
        "com::example::runPlain",
        "com::example::runNullableForce",
        "com::example::runHop",
        "com::example::runNullableHop",
    ] {
        assert!(
            persisted
                .callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing persisted caller {caller}"
        );
    }
}

