#[test]
fn traces_kotlin_property_chain_initializer_method_call_hops_in_live_workspace_and_persisted_index()
{
    let dir = temporary_dir();
    let source_path = dir.join("Callers.kt");
    let db_path = dir.join("symbols.db");
    fs::write(
        &source_path,
        "package com.example\n\nclass Item {\n    fun helper(value: Int): Int = value\n}\n\nclass Holder {\n    val item: Item = Item()\n    fun make(): Holder = Holder()\n}\n\nopen class Base {\n    val holder: Holder = Holder()\n    fun make(): Holder = Holder()\n}\n\nclass Util : Base() {\n    fun runCallThenProp(): Int {\n        val first = make().item\n        return first.helper(1)\n    }\n    fun runThisCallProp(): Int {\n        val first = this.make().item\n        return first.helper(2)\n    }\n    fun runSuperCallProp(): Int {\n        val first = super.make().item\n        return first.helper(3)\n    }\n    fun runThisPropCallProp(): Int {\n        val first = this.holder.make().item\n        return first.helper(4)\n    }\n    fun runBarePropCallProp(): Int {\n        val first = holder.make().item\n        return first.helper(5)\n    }\n    fun runParen(): Int {\n        val first = (make().item)\n        return first.helper(6)\n    }\n}\n",
    )
    .unwrap();

    // A `val` local bound from a property-chain initializer whose chain
    // contains a method-call hop, such as `val first = make().item`,
    // `val first = this.make().item`, `val first = super.make().item`, or
    // `val first = this.holder.make().item`, dispatches through the
    // enclosing type's own or inherited member function declared return type
    // and each remaining property hop before its member calls resolve on the
    // terminal property type; parenthesized spellings unwrap the same way.
    // All six callers trace to `Item::helper`.
    let item_path = "com::example::Item::helper";
    let live = trace_symbol_graph(&dir, item_path, TraceDirection::Callers).unwrap();
    assert_eq!(live.symbol.symbol_id, item_path);
    assert_eq!(live.callers.len(), 6);
    for caller in [
        "com::example::Util::runCallThenProp",
        "com::example::Util::runThisCallProp",
        "com::example::Util::runSuperCallProp",
        "com::example::Util::runThisPropCallProp",
        "com::example::Util::runBarePropCallProp",
        "com::example::Util::runParen",
    ] {
        assert!(
            live.callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing caller {caller}"
        );
    }

    rebuild_symbol_index(&dir, &db_path).unwrap();
    let persisted =
        trace_symbol_graph_from_index(&db_path, item_path, TraceDirection::Callers).unwrap();
    assert_eq!(persisted.callers.len(), 6);
    for caller in [
        "com::example::Util::runCallThenProp",
        "com::example::Util::runThisCallProp",
        "com::example::Util::runSuperCallProp",
        "com::example::Util::runThisPropCallProp",
        "com::example::Util::runBarePropCallProp",
        "com::example::Util::runParen",
    ] {
        assert!(
            persisted
                .callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing persisted caller {caller}"
        );
    }
}

