#[test]
fn kotlin_implicit_companion_function_receiver_calls_fail_closed_for_unsupported_references() {
    let dir = temporary_dir();
    let source_path = dir.join("Callers.kt");
    let db_path = dir.join("symbols.db");
    fs::write(
        &source_path,
        "package com.example\n\nclass Item {\n    fun helper(value: Int): Int = value\n}\n\nclass Helper {\n    fun inner(): Item = Item()\n}\n\nclass NoCompanion {\n    fun run(): Int {\n        return make().helper(1)\n    }\n}\n\nclass Util {\n    companion object {\n        fun make(): Item = Item()\n        fun makeUntyped() {}\n        fun makeHelper(): Helper = Helper()\n        fun makeCount(): Int = 0\n    }\n    fun failUnknown(): Int {\n        return missing().helper(1)\n    }\n    fun failNoReturnType(): Int {\n        return makeUntyped().helper(1)\n    }\n    fun failNonItemHop(): Int {\n        return makeHelper().helper(1)\n    }\n    fun failPrimitive(): Int {\n        return makeCount().helper(1)\n    }\n    fun control(): Int {\n        return make().helper(1)\n    }\n}\n\nfun failTopLevel(): Int {\n    return make().helper(1)\n}\n",
    )
    .unwrap();

    // Implicit companion function references fail closed for unknown
    // functions (`missing()`), companion functions without a declared return
    // type (`makeUntyped()`), return types without the trailing member
    // (`makeHelper()` returns `Helper`, which has no `helper`), primitive
    // returns (`makeCount()`), types without a companion object
    // (`NoCompanion`), and bare companion function calls in top-level
    // functions, where there is no enclosing companion scope; only the
    // resolvable chain in `control` traces.
    let item_path = "com::example::Item::helper";
    let live = trace_symbol_graph(&dir, item_path, TraceDirection::Callers).unwrap();
    assert_eq!(live.callers.len(), 1);
    assert_eq!(live.callers[0].symbol_id, "com::example::Util::control");

    rebuild_symbol_index(&dir, &db_path).unwrap();
    let persisted =
        trace_symbol_graph_from_index(&db_path, item_path, TraceDirection::Callers).unwrap();
    assert_eq!(persisted.callers.len(), 1);
    assert_eq!(
        persisted.callers[0].symbol_id,
        "com::example::Util::control"
    );
}

