#[test]
fn traces_kotlin_this_and_super_rooted_hierarchy_member_calls_in_live_workspace_and_persisted_index()
 {
    let dir = temporary_dir();
    let source_path = dir.join("Callers.kt");
    let db_path = dir.join("symbols.db");
    fs::write(
        &source_path,
        "package com.example\n\nopen class Grand {\n    fun grandHelper(value: Int): Int = value\n}\nopen class Mid : Grand()\nopen class Base : Mid()\ninterface Root {\n    fun render(value: Int): Int = value\n}\nclass Caller : Base(), Root {\n    fun run(): Int {\n        return this.grandHelper(1) + this.render(2) + super.grandHelper(3)\n    }\n}\n",
    )
    .unwrap();

    // A `this.`-rooted call dispatches members inherited through the enclosing
    // type's superclass chain and implemented-interface fallback, and a
    // `super.`-rooted call continues up the direct superclass chain beyond the
    // immediate superclass.
    for target in [
        "com::example::Grand::grandHelper",
        "com::example::Root::render",
    ] {
        let live = trace_symbol_graph(&dir, target, TraceDirection::Callers).unwrap();
        assert_eq!(live.symbol.symbol_id, target);
        assert_eq!(live.callers.len(), 1);
        assert_eq!(live.callers[0].symbol_id, "com::example::Caller::run");
    }

    rebuild_symbol_index(&dir, &db_path).unwrap();
    for target in [
        "com::example::Grand::grandHelper",
        "com::example::Root::render",
    ] {
        let persisted =
            trace_symbol_graph_from_index(&db_path, target, TraceDirection::Callers).unwrap();
        assert_eq!(persisted.callers.len(), 1);
        assert_eq!(persisted.callers[0].symbol_id, "com::example::Caller::run");
    }
}

