#[test]
fn traces_kotlin_class_receiver_diamond_interface_chain_hop_receiver_calls_in_live_workspace_and_persisted_index()
 {
    let dir = temporary_dir();
    let source_path = dir.join("Callers.kt");
    let db_path = dir.join("symbols.db");
    fs::write(
        &source_path,
        "package com.example\n\nclass Entry {\n    fun helper(value: Int): Int = value\n}\ninterface Root {\n    val entry: Entry\n    fun inner(): Entry\n}\ninterface Left : Root\ninterface Right : Root\ninterface Diamond : Left, Right\nclass Impl : Diamond\n\nfun hopCaller(impl: Impl): Int {\n    return impl.inner().helper(1) + impl.entry.helper(2)\n}\n",
    )
    .unwrap();

    // Property and method-call hops on a class-typed receiver resolve through
    // a diamond-shaped implemented-interface graph exactly once, so hops
    // declared on the shared ancestor continue the chain on the inherited
    // declared type.
    let helper_path = "com::example::Entry::helper";
    let live = trace_symbol_graph(&dir, helper_path, TraceDirection::Callers).unwrap();
    assert_eq!(live.symbol.symbol_id, helper_path);
    assert_eq!(live.callers.len(), 1);
    assert_eq!(live.callers[0].symbol_id, "com::example::hopCaller");

    rebuild_symbol_index(&dir, &db_path).unwrap();
    let persisted =
        trace_symbol_graph_from_index(&db_path, helper_path, TraceDirection::Callers).unwrap();
    assert_eq!(persisted.callers.len(), 1);
    assert_eq!(persisted.callers[0].symbol_id, "com::example::hopCaller");
}

