#[test]
fn traces_kotlin_cross_file_dotted_alias_receiver_calls_in_live_workspace_and_persisted_index() {
    let dir = temporary_dir();
    let caller_path = dir.join("Caller.kt");
    let base_path = dir.join("Base.kt");
    let db_path = dir.join("symbols.db");
    fs::write(
        &caller_path,
        "package com.example\n\nimport org.util.Outer as O\n\nfun constructorCaller(): Int {\n    val inner = O.Inner()\n    return inner.helper(1)\n}\n\nfun companionCaller(): Int = O.Inner.Companion.helper(1)\n\nfun propertyCaller(): Int {\n    val group = O.Group()\n    return group.holder.member.helper(1)\n}\n",
    )
    .unwrap();
    fs::write(
        &base_path,
        "package org.util\n\nclass Holder {\n    val member: Member = Member()\n}\nclass Member {\n    fun helper(value: Int): Int = value\n}\nclass Outer {\n    class Inner {\n        fun helper(value: Int): Int = value\n        companion object {\n            fun helper(value: Int): Int = value\n        }\n    }\n    class Group {\n        val holder: Holder = Holder()\n    }\n}\n",
    )
    .unwrap();

    // An aliased import of an outer type such as `import org.util.Outer as O`
    // resolves dotted nested constructors (`O.Inner()`), dotted nested
    // companions (`O.Inner.Companion.helper(...)`), and dotted nested types in
    // property chains (`O.Group().holder.member.helper(...)`) across packages.
    let instance_helper_path = "org::util::Outer::Inner::helper";
    let live = trace_symbol_graph(&dir, instance_helper_path, TraceDirection::Callers).unwrap();
    assert_eq!(live.indexed_files, 2);
    assert_eq!(live.symbol.symbol_id, instance_helper_path);
    assert_eq!(live.callers.len(), 1);
    assert_eq!(live.callers[0].symbol_id, "com::example::constructorCaller");

    let companion_helper_path = "org::util::Outer::Inner::Companion::helper";
    let live = trace_symbol_graph(&dir, companion_helper_path, TraceDirection::Callers).unwrap();
    assert_eq!(live.indexed_files, 2);
    assert_eq!(live.callers.len(), 1);
    assert_eq!(live.callers[0].symbol_id, "com::example::companionCaller");

    let member_helper_path = "org::util::Member::helper";
    let live = trace_symbol_graph(&dir, member_helper_path, TraceDirection::Callers).unwrap();
    assert_eq!(live.indexed_files, 2);
    assert_eq!(live.callers.len(), 1);
    assert_eq!(live.callers[0].symbol_id, "com::example::propertyCaller");

    rebuild_symbol_index(&dir, &db_path).unwrap();
    for (target, caller) in [
        (instance_helper_path, "com::example::constructorCaller"),
        (companion_helper_path, "com::example::companionCaller"),
        (member_helper_path, "com::example::propertyCaller"),
    ] {
        let persisted =
            trace_symbol_graph_from_index(&db_path, target, TraceDirection::Callers).unwrap();
        assert_eq!(persisted.indexed_files, 2);
        assert_eq!(persisted.callers.len(), 1);
        assert_eq!(persisted.callers[0].symbol_id, caller);
    }
}

