#[test]
fn java_var_factory_method_hop_field_receiver_calls_fail_closed_for_unsupported_references() {
    let dir = temporary_dir();
    let source_path = dir.join("Types.java");
    let db_path = dir.join("symbols.db");
    fs::write(
        &source_path,
        "package com.example;
class Entry { int helper(int value) { return value; } }
class Group { Entry entry = new Entry(); }
class Util {
    static Group make(int value) { return new Group(); }
}
class Caller {
    Group make(int value) { return new Group(); }
    void makeVoid() { }
    int primitive() { return 0; }
    int arityMismatch() {
        var v = make().entry;
        return v.helper(1);
    }
    int staticArityMismatch() {
        var v = Util.make().entry;
        return v.helper(1);
    }
    int unknownFactory() {
        var v = missing().entry;
        return v.helper(1);
    }
    int voidFactory() {
        var v = makeVoid().entry;
        return v.helper(1);
    }
    int primitiveFactory() {
        var v = primitive().entry;
        return v.helper(1);
    }
}
",
    )
    .unwrap();

    let target = "com::example::Entry::helper";
    let live = trace_symbol_graph(&dir, target, TraceDirection::Callers).unwrap();
    assert!(
        live.callers.is_empty(),
        "arity-mismatched, unknown, void-returning, and primitive-returning factory method-call hops must fail closed"
    );

    rebuild_symbol_index(&dir, &db_path).unwrap();
    let persisted =
        trace_symbol_graph_from_index(&db_path, target, TraceDirection::Callers).unwrap();
    assert!(persisted.callers.is_empty());
}

#[test]
fn traces_kotlin_property_chain_initializer_element_access_hop_bindings_in_live_workspace_and_persisted_index()
 {
    let dir = temporary_dir();
    let source_path = dir.join("Callers.kt");
    let db_path = dir.join("symbols.db");
    fs::write(
        &source_path,
        "package com.example\n\nclass Item {\n    fun helper(value: Int): Int = value\n}\n\nclass Inner {\n    fun inner(): Item = Item()\n    val item: Item = Item()\n}\n\nclass Maker {\n    fun make(): Array<Item> = arrayOf()\n}\n\nclass Holder {\n    val items: Array<Maker> = arrayOf()\n    val inners: Array<Inner> = arrayOf()\n    val item: Item = Item()\n}\n\nclass Util {\n    val memberItems: Array<Maker> = arrayOf()\n\n    fun runBoundElemFactory(): Int {\n        val h = Holder()\n        val x = h.items[0].make()\n        return x[0].helper(1)\n    }\n    fun runBoundElemFactoryRebound(): Int {\n        val h = Holder()\n        val x = h.items[0].make()\n        val first = x\n        return first[0].helper(2)\n    }\n    fun runBoundElemProp(): Int {\n        val h = Holder()\n        val first = h.inners[0].item\n        return first.helper(3)\n    }\n    fun runBareMemberElemFactory(): Int {\n        val x = memberItems[0].make()\n        val first = x\n        return first[0].helper(4)\n    }\n    fun runBoundElemMethod(): Int {\n        val h = Holder()\n        val first = h.inners[0].inner()\n        return first.helper(5)\n    }\n    fun runInlineElemFactory(): Int {\n        val h = Holder()\n        return h.items[0].make()[0].helper(6)\n    }\n}\n\nclass Util2 {\n    fun runNonZeroArgFailsClosed(): Int {\n        val h = Holder()\n        val x = h.items[0].make(1)\n        return x[0].helper(7)\n    }\n    fun runBoundNonArrayFailsClosed(): Int {\n        val h = Holder()\n        val first = h.item\n        return first[0].helper(8)\n    }\n}\n",
    )
    .unwrap();

    // Property-chain initializers whose spelling contains single-level
    // element-access hops also bind and trace: a bound-receiver factory
    // terminal (`val x = h.items[0].make()` with `h.items: Array<Maker>` and
    // `fun make(): Array<Item>`), its re-bound form (`val first = x`), a
    // property terminal after the element-access hop
    // (`val first = h.inners[0].item`), a bare member array factory terminal
    // (`val x = memberItems[0].make()`), a method-call terminal
    // (`val first = h.inners[0].inner()`), and the direct inline multi-hop
    // factory element access (`h.items[0].make()[0].helper(...)`). A
    // non-zero-argument call (`h.items[0].make(1)`) and element access on a
    // bound non-array value (`val first = h.item` then `first[0]`) fail
    // closed, so only the six array- or value-rooted callers dispatch on
    // `Item::helper`.
    let item_path = "com::example::Item::helper";
    let live = trace_symbol_graph(&dir, item_path, TraceDirection::Callers).unwrap();
    assert_eq!(live.symbol.symbol_id, item_path);
    assert_eq!(live.callers.len(), 6);
    for caller in [
        "com::example::Util::runBoundElemFactory",
        "com::example::Util::runBoundElemFactoryRebound",
        "com::example::Util::runBoundElemProp",
        "com::example::Util::runBareMemberElemFactory",
        "com::example::Util::runBoundElemMethod",
        "com::example::Util::runInlineElemFactory",
    ] {
        assert!(
            live.callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing caller {caller}"
        );
    }

    rebuild_symbol_index(&dir, &db_path).unwrap();
    let persisted =
        trace_symbol_graph_from_index(&db_path, item_path, TraceDirection::Callers).unwrap();
    assert_eq!(persisted.callers.len(), 6);
    for caller in [
        "com::example::Util::runBoundElemFactory",
        "com::example::Util::runBoundElemFactoryRebound",
        "com::example::Util::runBoundElemProp",
        "com::example::Util::runBareMemberElemFactory",
        "com::example::Util::runBoundElemMethod",
        "com::example::Util::runInlineElemFactory",
    ] {
        assert!(
            persisted
                .callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing persisted caller {caller}"
        );
    }
}
#[test]
fn traces_kotlin_property_chain_initializer_top_level_array_element_access_hop_roots_in_live_workspace_and_persisted_index()
 {
    let dir = temporary_dir();
    let source_path = dir.join("Callers.kt");
    let helper_path = dir.join("Helper.kt");
    let db_path = dir.join("symbols.db");
    fs::write(
        &source_path,
        "package com.example\n\nval itemGroup: Array<Maker> = arrayOf()\nval itemGroup2: Array<Maker> = arrayOf()\n\nclass Item {\n    fun helper(value: Int): Int = value\n}\n\nclass Maker {\n    fun make(): Array<Item> = arrayOf()\n}\n\nclass Util {\n    val itemGroup: Array<Maker> = arrayOf()\n    val itemGroup2: Maker = Maker()\n\n    fun runMemberArrayShadowing(): Int {\n        val x = itemGroup[0].make()\n        val first = x\n        return first[0].helper(1)\n    }\n    fun runMemberNonArrayShadowingFailsClosed(): Int {\n        val x = itemGroup2[0].make()\n        val first = x\n        return first[0].helper(2)\n    }\n}\n\nclass Util2 {\n    fun runTopLevelElemHop(): Int {\n        val x = itemGroup[0].make()\n        val first = x\n        return first[0].helper(3)\n    }\n}\n",
    )
    .unwrap();
    fs::write(
        &helper_path,
        "package org.util\n\nval sharedGroup: Array<Maker> = arrayOf()\n\nclass Item {\n    fun helper(value: Int): Int = value\n}\n\nclass Maker {\n    fun make(): Array<Item> = arrayOf()\n}\n",
    )
    .unwrap();
    fs::write(
        dir.join("Imported.kt"),
        "package com.example\n\nimport org.util.sharedGroup\n\nclass Util3 {\n    fun runImportedTopLevelElemHop(): Int {\n        val x = sharedGroup[0].make()\n        val first = x\n        return first[0].helper(4)\n    }\n}\n",
    )
    .unwrap();

    // A leading single-level element-access hop in a property-chain
    // initializer may index a same-package top-level array property
    // (`val x = itemGroup[0].make()` with `val itemGroup: Array<Maker>` at
    // package scope) or an explicitly imported top-level array property from
    // another package (`val x = sharedGroup[0].make()`); the terminal
    // factory hop's declared return array element component type dispatches
    // `first[0].helper(...)`. An own member array shadows the same-named
    // top-level property and still traces, while an own non-array member
    // shadows the top-level property and fails closed, so the same-package
    // callers in `Util`/`Util2` dispatch on `com::example::Item::helper`,
    // the imported caller in `Util3` dispatches on `org::util::Item::helper`,
    // and `Util::runMemberNonArrayShadowingFailsClosed` traces neither.
    let item_path = "com::example::Item::helper";
    let live = trace_symbol_graph(&dir, item_path, TraceDirection::Callers).unwrap();
    assert_eq!(live.symbol.symbol_id, item_path);
    assert_eq!(live.callers.len(), 2);
    for caller in [
        "com::example::Util::runMemberArrayShadowing",
        "com::example::Util2::runTopLevelElemHop",
    ] {
        assert!(
            live.callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing caller {caller}"
        );
    }

    let imported_item_path = "org::util::Item::helper";
    let live_imported =
        trace_symbol_graph(&dir, imported_item_path, TraceDirection::Callers).unwrap();
    assert_eq!(live_imported.symbol.symbol_id, imported_item_path);
    assert_eq!(live_imported.callers.len(), 1);
    assert!(
        live_imported
            .callers
            .iter()
            .any(|candidate| candidate.symbol_id
                == "com::example::Util3::runImportedTopLevelElemHop")
    );

    rebuild_symbol_index(&dir, &db_path).unwrap();
    let persisted =
        trace_symbol_graph_from_index(&db_path, item_path, TraceDirection::Callers).unwrap();
    assert_eq!(persisted.callers.len(), 2);
    for caller in [
        "com::example::Util::runMemberArrayShadowing",
        "com::example::Util2::runTopLevelElemHop",
    ] {
        assert!(
            persisted
                .callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing persisted caller {caller}"
        );
    }
    let persisted_imported =
        trace_symbol_graph_from_index(&db_path, imported_item_path, TraceDirection::Callers)
            .unwrap();
    assert_eq!(persisted_imported.callers.len(), 1);
    assert!(
        persisted_imported
            .callers
            .iter()
            .any(|candidate| candidate.symbol_id
                == "com::example::Util3::runImportedTopLevelElemHop")
    );
}
#[test]
fn traces_kotlin_property_chain_initializer_factory_element_access_hops_in_live_workspace_and_persisted_index()
 {
    let dir = temporary_dir();
    let source_path = dir.join("Callers.kt");
    let helper_path = dir.join("Helper.kt");
    let db_path = dir.join("symbols.db");
    fs::write(
        &source_path,
        "package com.example\n\nclass Item {\n    fun helper(value: Int): Int = value\n}\n\nclass Inner {\n    fun inner(): Item = Item()\n    fun makeGroups(): Array<Inner> = arrayOf()\n    val item: Item = Item()\n    val items: Array<Item> = arrayOf()\n}\n\nclass Holder {\n    fun makeGroups(): Array<Inner> = arrayOf()\n}\n\nclass NonArrayHolder {\n    fun makeGroups(): Inner = Inner()\n}\n\nfun makeGroups(): Array<Inner> = arrayOf()\n\nclass Util {\n    fun runBoundProp(): Int {\n        val h = Holder()\n        val first = h.makeGroups()[0].item\n        return first.helper(1)\n    }\n    fun runBoundMethod(): Int {\n        val h = Holder()\n        val first = h.makeGroups()[0].inner()\n        return first.helper(2)\n    }\n    fun runTopLevel(): Int {\n        val first = makeGroups()[0].item\n        return first.helper(3)\n    }\n    fun runArrayTerminal(): Int {\n        val h = Holder()\n        val first = h.makeGroups()[0].items\n        return first[0].helper(4)\n    }\n    fun runMultiHop(): Int {\n        val h = Holder()\n        val first = h.makeGroups()[0].makeGroups()[0].item\n        return first.helper(5)\n    }\n    fun runNonArrayFactoryFailsClosed(): Int {\n        val nh = NonArrayHolder()\n        val first = nh.makeGroups()[0].item\n        return first.helper(6)\n    }\n    fun runUnknownFactoryFailsClosed(): Int {\n        val h = Holder()\n        val first = h.missing()[0].item\n        return first.helper(7)\n    }\n}\n",
    )
    .unwrap();
    fs::write(
        &helper_path,
        "package org.util\n\nclass ImportedItem {\n    fun helper(value: Int): Int = value\n}\n\nclass ImportedInner {\n    val item: ImportedItem = ImportedItem()\n}\n\nclass ImportedHolder {\n    fun makeGroups(): Array<ImportedInner> = arrayOf()\n}\n",
    )
    .unwrap();
    fs::write(
        dir.join("Imported.kt"),
        "package com.example\n\nimport org.util.ImportedHolder\n\nclass Util2 {\n    fun runImported(): Int {\n        val h = ImportedHolder()\n        val first = h.makeGroups()[0].item\n        return first.helper(8)\n    }\n}\n",
    )
    .unwrap();

    // Factory element-access hops (`makeGroups()[0]`) inside a
    // property-chain initializer resolve the factory's declared return array
    // element component type and walk the remaining hops: a bound-receiver
    // factory followed by a property terminal (`h.makeGroups()[0].item`), a
    // method terminal (`h.makeGroups()[0].inner()`), a same-file top-level
    // factory (`makeGroups()[0].item`), a terminal array property
    // (`h.makeGroups()[0].items` then `first[0].helper(...)`), and stacked
    // factory hops (`h.makeGroups()[0].makeGroups()[0].item`). A factory
    // returning a non-array and an unknown factory fail closed, so the five
    // same-package callers in `Util` dispatch on `com::example::Item::helper`
    // and the imported caller in `Util2` dispatches on
    // `org::util::ImportedItem::helper`.
    let item_path = "com::example::Item::helper";
    let live = trace_symbol_graph(&dir, item_path, TraceDirection::Callers).unwrap();
    assert_eq!(live.symbol.symbol_id, item_path);
    assert_eq!(live.callers.len(), 5);
    for caller in [
        "com::example::Util::runBoundProp",
        "com::example::Util::runBoundMethod",
        "com::example::Util::runTopLevel",
        "com::example::Util::runArrayTerminal",
        "com::example::Util::runMultiHop",
    ] {
        assert!(
            live.callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing caller {caller}"
        );
    }

    let imported_item_path = "org::util::ImportedItem::helper";
    let live_imported =
        trace_symbol_graph(&dir, imported_item_path, TraceDirection::Callers).unwrap();
    assert_eq!(live_imported.symbol.symbol_id, imported_item_path);
    assert_eq!(live_imported.callers.len(), 1);
    assert!(
        live_imported
            .callers
            .iter()
            .any(|candidate| candidate.symbol_id == "com::example::Util2::runImported")
    );

    rebuild_symbol_index(&dir, &db_path).unwrap();
    let persisted =
        trace_symbol_graph_from_index(&db_path, item_path, TraceDirection::Callers).unwrap();
    assert_eq!(persisted.callers.len(), 5);
    for caller in [
        "com::example::Util::runBoundProp",
        "com::example::Util::runBoundMethod",
        "com::example::Util::runTopLevel",
        "com::example::Util::runArrayTerminal",
        "com::example::Util::runMultiHop",
    ] {
        assert!(
            persisted
                .callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing persisted caller {caller}"
        );
    }
    let persisted_imported =
        trace_symbol_graph_from_index(&db_path, imported_item_path, TraceDirection::Callers)
            .unwrap();
    assert_eq!(persisted_imported.callers.len(), 1);
    assert!(
        persisted_imported
            .callers
            .iter()
            .any(|candidate| candidate.symbol_id == "com::example::Util2::runImported")
    );
}

#[test]
fn traces_kotlin_property_chain_initializer_method_call_element_access_bases_in_live_workspace_and_persisted_index()
 {
    let dir = temporary_dir();
    let source_path = dir.join("Callers.kt");
    let helper_path = dir.join("Helper.kt");
    let db_path = dir.join("symbols.db");
    fs::write(
        &source_path,
        "package com.example\n\nclass Item {\n    fun helper(value: Int): Int = value\n}\n\nclass Inner {\n    fun inner(): Item = Item()\n    fun make(): Group = Group()\n    val item: Item = Item()\n    val items: Array<Item> = arrayOf()\n}\n\nclass Group {\n    val items: Array<Inner> = arrayOf()\n    fun make(): Group = Group()\n}\n\nclass Holder {\n    fun make(): Group = Group()\n}\n\nclass Util {\n    fun runBoundElemBase(): Int {\n        val h = Holder()\n        val group = h.make().items[0]\n        val first = group.item\n        return first.helper(1)\n    }\n    fun runMultiHopElemBase(): Int {\n        val h = Holder()\n        val group = h.make().make().items[0]\n        val first = group.item\n        return first.helper(2)\n    }\n    fun runStackedElemBase(): Int {\n        val h = Holder()\n        val group = h.make().items[0].make().items[0]\n        val first = group.item\n        return first.helper(3)\n    }\n    fun runArrayTerminalElemBase(): Int {\n        val h = Holder()\n        val group = h.make().items[0].items\n        return group[0].helper(4)\n    }\n    fun runDirectChain(): Int {\n        val h = Holder()\n        val first = h.make().items[0].item\n        return first.helper(5)\n    }\n    fun runChainRootThenElem(): Int {\n        val h = Holder()\n        val group = h.make().items[0]\n        val first = group.make().items[0].item\n        return first.helper(6)\n    }\n    fun runUnknownMethodFailsClosed(): Int {\n        val h = Holder()\n        val group = h.missing().items[0]\n        val first = group.item\n        return first.helper(7)\n    }\n}\n",
    )
    .unwrap();
    fs::write(
        &helper_path,
        "package org.util\n\nclass ImportedItem {\n    fun helper(value: Int): Int = value\n}\n\nclass ImportedInner {\n    val item: ImportedItem = ImportedItem()\n}\n\nclass ImportedGroup {\n    val items: Array<ImportedInner> = arrayOf()\n}\n\nclass ImportedHolder {\n    fun make(): ImportedGroup = ImportedGroup()\n}\n",
    )
    .unwrap();
    fs::write(
        dir.join("Imported.kt"),
        "package com.example\n\nimport org.util.ImportedHolder\n\nclass Util2 {\n    fun runImported(): Int {\n        val h = ImportedHolder()\n        val group = h.make().items[0]\n        val first = group.item\n        return first.helper(8)\n    }\n}\n",
    )
    .unwrap();

    // Element-access initializers whose base chain contains a method-call hop
    // (`h.make().items[0]`) record as property chains so trace-time
    // resolution can walk the method-call and element-access hops to the
    // terminal array component: a bound receiver followed by a method-call
    // hop and a property terminal (`val group = h.make().items[0]` then
    // `group.item`), stacked method-call hops (`h.make().make().items[0]`),
    // an element-access hop followed by another method-call hop
    // (`h.make().items[0].make().items[0]`), a terminal array property used
    // as an element-access receiver (`val group = h.make().items[0].items`
    // then `group[0].helper(...)`), the direct inline form
    // (`val first = h.make().items[0].item`), and a bound element-access root
    // used with further element-access hops (`group.make().items[0].item`).
    // An unknown method-call hop fails closed, so the six same-package
    // callers in `Util` dispatch on `com::example::Item::helper` and the
    // imported caller in `Util2` dispatches on
    // `org::util::ImportedItem::helper`.
    let item_path = "com::example::Item::helper";
    let live = trace_symbol_graph(&dir, item_path, TraceDirection::Callers).unwrap();
    assert_eq!(live.symbol.symbol_id, item_path);
    assert_eq!(live.callers.len(), 6);
    for caller in [
        "com::example::Util::runBoundElemBase",
        "com::example::Util::runMultiHopElemBase",
        "com::example::Util::runStackedElemBase",
        "com::example::Util::runArrayTerminalElemBase",
        "com::example::Util::runDirectChain",
        "com::example::Util::runChainRootThenElem",
    ] {
        assert!(
            live.callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing caller {caller}"
        );
    }

    let imported_item_path = "org::util::ImportedItem::helper";
    let live_imported =
        trace_symbol_graph(&dir, imported_item_path, TraceDirection::Callers).unwrap();
    assert_eq!(live_imported.symbol.symbol_id, imported_item_path);
    assert_eq!(live_imported.callers.len(), 1);
    assert!(
        live_imported
            .callers
            .iter()
            .any(|candidate| candidate.symbol_id == "com::example::Util2::runImported")
    );

    rebuild_symbol_index(&dir, &db_path).unwrap();
    let persisted =
        trace_symbol_graph_from_index(&db_path, item_path, TraceDirection::Callers).unwrap();
    assert_eq!(persisted.callers.len(), 6);
    for caller in [
        "com::example::Util::runBoundElemBase",
        "com::example::Util::runMultiHopElemBase",
        "com::example::Util::runStackedElemBase",
        "com::example::Util::runArrayTerminalElemBase",
        "com::example::Util::runDirectChain",
        "com::example::Util::runChainRootThenElem",
    ] {
        assert!(
            persisted
                .callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing persisted caller {caller}"
        );
    }
    let persisted_imported =
        trace_symbol_graph_from_index(&db_path, imported_item_path, TraceDirection::Callers)
            .unwrap();
    assert_eq!(persisted_imported.callers.len(), 1);
    assert!(
        persisted_imported
            .callers
            .iter()
            .any(|candidate| candidate.symbol_id == "com::example::Util2::runImported")
    );
}

#[test]
fn traces_kotlin_dotted_factory_call_bindings_in_live_workspace_and_persisted_index() {
    let dir = temporary_dir();
    let source_path = dir.join("Callers.kt");
    let helper_path = dir.join("Helper.kt");
    let db_path = dir.join("symbols.db");
    fs::write(
        &source_path,
        "package com.example\n\nclass Item {\n    fun helper(value: Int): Int = value\n}\n\nclass Inner {\n    fun inner(): Item = Item()\n    fun make(): Group = Group()\n    val item: Item = Item()\n    val items: Array<Item> = arrayOf()\n}\n\nclass Group {\n    val items: Array<Inner> = arrayOf()\n    fun make(): Group = Group()\n}\n\nobject Factory {\n    fun make(): Group = Group()\n}\n\nclass Holder {\n    fun make(): Group = Group()\n    companion object {\n        fun make(): Group = Group()\n    }\n}\n\nopen class BaseUtil {\n    fun make(): Group = Group()\n}\n\nfun make(): Group = Group()\n\nclass Util : BaseUtil() {\n    fun make(): Group = Group()\n\n    fun runBoundLocalReceiver(): Int {\n        val h = Holder()\n        val group = h.make()\n        val first = group.items[0].item\n        return first.helper(1)\n    }\n    fun runThisFactory(): Int {\n        val group = this.make()\n        val first = group.items[0].item\n        return first.helper(2)\n    }\n    fun runSuperFactory(): Int {\n        val group = super.make()\n        val first = group.items[0].item\n        return first.helper(3)\n    }\n    fun runObjectFactory(): Int {\n        val group = Factory.make()\n        val first = group.items[0].item\n        return first.helper(4)\n    }\n    fun runCompanionFactory(): Int {\n        val group = Holder.make()\n        val first = group.items[0].item\n        return first.helper(5)\n    }\n    fun runElemBaseThenMethod(): Int {\n        val h = Holder()\n        val group = h.make().items[0]\n        val first = group.inner()\n        return first.helper(6)\n    }\n    fun runBoundThenBound(): Int {\n        val h = Holder()\n        val group = h.make()\n        val first = group.make().items[0].item\n        return first.helper(7)\n    }\n    fun runBoundThenArrayTerminal(): Int {\n        val h = Holder()\n        val group = h.make()\n        val first = group.items[0]\n        return first.item.helper(8)\n    }\n    fun runNamedCompanionFailsClosed(): Int {\n        val group = Holder.Factory.make()\n        val first = group.items[0].item\n        return first.helper(9)\n    }\n    fun runUnknownMethodFailsClosed(): Int {\n        val h = Holder()\n        val group = h.missing()\n        val first = group.items[0].item\n        return first.helper(10)\n    }\n}\n",
    )
    .unwrap();
    fs::write(
        &helper_path,
        "package org.util\n\nclass ImportedItem {\n    fun helper(value: Int): Int = value\n}\n\nclass ImportedInner {\n    fun inner(): ImportedItem = ImportedItem()\n    fun make(): ImportedGroup = ImportedGroup()\n    val item: ImportedItem = ImportedItem()\n    val items: Array<ImportedItem> = arrayOf()\n}\n\nclass ImportedGroup {\n    val items: Array<ImportedInner> = arrayOf()\n}\n\nclass ImportedHolder {\n    fun make(): ImportedGroup = ImportedGroup()\n}\n\nobject ImportedFactory {\n    fun make(): ImportedGroup = ImportedGroup()\n}\n\nclass ImportedCompanionHolder {\n    companion object {\n        fun make(): ImportedGroup = ImportedGroup()\n    }\n}\n",
    )
    .unwrap();
    fs::write(
        dir.join("Imported.kt"),
        "package com.example\n\nimport org.util.ImportedHolder\nimport org.util.ImportedFactory\nimport org.util.ImportedCompanionHolder\n\nclass Util2 {\n    fun runImportedBound(): Int {\n        val h = ImportedHolder()\n        val group = h.make()\n        val first = group.items[0].item\n        return first.helper(11)\n    }\n    fun runImportedObject(): Int {\n        val group = ImportedFactory.make()\n        val first = group.items[0].item\n        return first.helper(12)\n    }\n    fun runImportedCompanion(): Int {\n        val group = ImportedCompanionHolder.make()\n        val first = group.items[0].item\n        return first.helper(13)\n    }\n}\n",
    )
    .unwrap();

    // Factory-inferred bindings from dotted method-call callees pin a `val`
    // local to the callee's declared return type through the same receiver
    // rules as a receiver chain: a locally bound receiver (`val group =
    // h.make()`), a `this`-rooted member (`this.make()`), a `super`-rooted
    // member (`super.make()`), a named object (`Factory.make()`), a type
    // with an anonymous companion (`Holder.make()`), an element-access
    // bound receiver used with a method terminal (`group.inner()` after
    // `val group = h.make().items[0]`), and chained bound receivers
    // (`group.make()` after `val group = h.make()` and terminal element
    // access on a bound array). A wrongly spelled named companion
    // (`Holder.Factory.make()`) and an unknown method (`h.missing()`) fail
    // closed, so the eight same-package callers in `Util` dispatch on
    // `com::example::Item::helper` and the three imported callers in `Util2`
    // dispatch on `org::util::ImportedItem::helper`.
    let item_path = "com::example::Item::helper";
    let live = trace_symbol_graph(&dir, item_path, TraceDirection::Callers).unwrap();
    assert_eq!(live.symbol.symbol_id, item_path);
    assert_eq!(live.callers.len(), 8);
    for caller in [
        "com::example::Util::runBoundLocalReceiver",
        "com::example::Util::runThisFactory",
        "com::example::Util::runSuperFactory",
        "com::example::Util::runObjectFactory",
        "com::example::Util::runCompanionFactory",
        "com::example::Util::runElemBaseThenMethod",
        "com::example::Util::runBoundThenBound",
        "com::example::Util::runBoundThenArrayTerminal",
    ] {
        assert!(
            live.callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing caller {caller}"
        );
    }

    let imported_item_path = "org::util::ImportedItem::helper";
    let live_imported =
        trace_symbol_graph(&dir, imported_item_path, TraceDirection::Callers).unwrap();
    assert_eq!(live_imported.symbol.symbol_id, imported_item_path);
    assert_eq!(live_imported.callers.len(), 3);
    for caller in [
        "com::example::Util2::runImportedBound",
        "com::example::Util2::runImportedObject",
        "com::example::Util2::runImportedCompanion",
    ] {
        assert!(
            live_imported
                .callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing caller {caller}"
        );
    }

    rebuild_symbol_index(&dir, &db_path).unwrap();
    let persisted =
        trace_symbol_graph_from_index(&db_path, item_path, TraceDirection::Callers).unwrap();
    assert_eq!(persisted.callers.len(), 8);
    for caller in [
        "com::example::Util::runBoundLocalReceiver",
        "com::example::Util::runThisFactory",
        "com::example::Util::runSuperFactory",
        "com::example::Util::runObjectFactory",
        "com::example::Util::runCompanionFactory",
        "com::example::Util::runElemBaseThenMethod",
        "com::example::Util::runBoundThenBound",
        "com::example::Util::runBoundThenArrayTerminal",
    ] {
        assert!(
            persisted
                .callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing persisted caller {caller}"
        );
    }
    let persisted_imported =
        trace_symbol_graph_from_index(&db_path, imported_item_path, TraceDirection::Callers)
            .unwrap();
    assert_eq!(persisted_imported.callers.len(), 3);
    for caller in [
        "com::example::Util2::runImportedBound",
        "com::example::Util2::runImportedObject",
        "com::example::Util2::runImportedCompanion",
    ] {
        assert!(
            persisted_imported
                .callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing persisted caller {caller}"
        );
    }
}

#[test]
fn traces_kotlin_property_chain_initializer_bound_array_element_access_roots_in_live_workspace_and_persisted_index()
 {
    let dir = temporary_dir();
    let source_path = dir.join("Callers.kt");
    let helper_path = dir.join("Helper.kt");
    let db_path = dir.join("symbols.db");
    fs::write(
        &source_path,
        "package com.example\n\nclass Item {\n    fun helper(value: Int): Int = value\n}\n\nclass Inner {\n    fun inner(): Item = Item()\n    val item: Item = Item()\n    val items: Array<Inner> = arrayOf()\n}\n\nclass Group {\n    val items: Array<Inner> = arrayOf()\n}\n\nclass Holder {\n    fun make(): Group = Group()\n    fun makeGroups(): Array<Inner> = arrayOf()\n}\n\nfun makeGroups(): Array<Inner> = arrayOf()\n\nclass Util {\n    fun makeGroups(): Array<Inner> = arrayOf()\n\n    fun runTopLevelBinding(): Int {\n        val group = makeGroups()\n        val first = group[0].item\n        return first.helper(1)\n    }\n    fun runClassBinding(): Int {\n        val group = this.makeGroups()\n        val first = group[0].item\n        return first.helper(2)\n    }\n    fun runBoundBinding(): Int {\n        val h = Holder()\n        val group = h.makeGroups()\n        val first = group[0].item\n        return first.helper(3)\n    }\n    fun runArrayParam(param: Array<Inner>): Int {\n        val first = param[0].item\n        return first.helper(4)\n    }\n    fun runLocalArrayBinding(): Int {\n        val items: Array<Inner> = arrayOf()\n        val first = items[0].item\n        return first.helper(5)\n    }\n    fun runDeeperChain(): Int {\n        val group = makeGroups()\n        val first = group[0].items[0].item\n        return first.helper(6)\n    }\n    fun runScalarFailsClosed(): Int {\n        val h = Holder()\n        val group = h.make()\n        val first = group[0].item\n        return first.helper(7)\n    }\n}\n",
    )
    .unwrap();
    fs::write(
        &helper_path,
        "package org.util\n\nclass ImportedItem {\n    fun helper(value: Int): Int = value\n}\n\nclass ImportedInner {\n    val item: ImportedItem = ImportedItem()\n}\n\nclass ImportedHolder {\n    fun makeGroups(): Array<ImportedInner> = arrayOf()\n}\n",
    )
    .unwrap();
    fs::write(
        dir.join("Imported.kt"),
        "package com.example\n\nimport org.util.ImportedHolder\n\nclass Util2 {\n    fun runImported(): Int {\n        val h = ImportedHolder()\n        val group = h.makeGroups()\n        val first = group[0].item\n        return first.helper(8)\n    }\n}\n",
    )
    .unwrap();

    // A `val` local bound from a property-chain initializer whose leading
    // element-access hop indexes a locally bound array value dispatches
    // through the bound name's array component type: a factory-call binding
    // (`val group = makeGroups()` then `group[0].item` from a same-file
    // top-level factory, a same-type member factory, a bound-receiver member
    // factory, or an explicitly imported holder factory), an array-typed
    // parameter (`param[0].item`), an array-typed local
    // (`val items: Array<Inner> = arrayOf()`), and deeper chains
    // (`group[0].items[0].item`). A bound scalar base such as
    // `val group = h.make()` followed by `group[0]` fails closed, so the six
    // same-package callers in `Util` dispatch on `com::example::Item::helper`
    // and the imported caller in `Util2` dispatches on
    // `org::util::ImportedItem::helper`.
    let item_path = "com::example::Item::helper";
    let live = trace_symbol_graph(&dir, item_path, TraceDirection::Callers).unwrap();
    assert_eq!(live.symbol.symbol_id, item_path);
    assert_eq!(live.callers.len(), 6);
    for caller in [
        "com::example::Util::runTopLevelBinding",
        "com::example::Util::runClassBinding",
        "com::example::Util::runBoundBinding",
        "com::example::Util::runArrayParam",
        "com::example::Util::runLocalArrayBinding",
        "com::example::Util::runDeeperChain",
    ] {
        assert!(
            live.callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing caller {caller}"
        );
    }

    let imported_item_path = "org::util::ImportedItem::helper";
    let live_imported =
        trace_symbol_graph(&dir, imported_item_path, TraceDirection::Callers).unwrap();
    assert_eq!(live_imported.symbol.symbol_id, imported_item_path);
    assert_eq!(live_imported.callers.len(), 1);
    assert!(
        live_imported
            .callers
            .iter()
            .any(|candidate| candidate.symbol_id == "com::example::Util2::runImported")
    );

    rebuild_symbol_index(&dir, &db_path).unwrap();
    let persisted =
        trace_symbol_graph_from_index(&db_path, item_path, TraceDirection::Callers).unwrap();
    assert_eq!(persisted.callers.len(), 6);
    for caller in [
        "com::example::Util::runTopLevelBinding",
        "com::example::Util::runClassBinding",
        "com::example::Util::runBoundBinding",
        "com::example::Util::runArrayParam",
        "com::example::Util::runLocalArrayBinding",
        "com::example::Util::runDeeperChain",
    ] {
        assert!(
            persisted
                .callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing persisted caller {caller}"
        );
    }
    let persisted_imported =
        trace_symbol_graph_from_index(&db_path, imported_item_path, TraceDirection::Callers)
            .unwrap();
    assert_eq!(persisted_imported.callers.len(), 1);
    assert!(
        persisted_imported
            .callers
            .iter()
            .any(|candidate| candidate.symbol_id == "com::example::Util2::runImported")
    );
}

#[test]
fn traces_kotlin_property_chain_initializer_chained_factory_call_bindings_in_live_workspace_and_persisted_index()
 {
    let dir = temporary_dir();
    let source_path = dir.join("Callers.kt");
    let helper_path = dir.join("Helper.kt");
    let db_path = dir.join("symbols.db");
    fs::write(
        &source_path,
        "package com.example\n\nclass Item {\n    fun helper(value: Int): Int = value\n}\n\nclass Inner {\n    fun inner(): Item = Item()\n    val item: Item = Item()\n    val items: Array<Item> = arrayOf()\n}\n\nclass Group {\n    val items: Array<Inner> = arrayOf()\n    fun make(): Group = Group()\n}\n\nclass Holder {\n    fun make(): Group = Group()\n}\n\nobject Factory {\n    fun make(): Group = Group()\n}\n\nopen class Base {\n    fun make(): Group = Group()\n}\n\nclass Util : Base() {\n    fun make(): Group = Group()\n\n    fun runBoundChained(): Int {\n        val h = Holder()\n        val group = h.make().make()\n        val first = group.items[0].item\n        return first.helper(1)\n    }\n    fun runObjectChained(): Int {\n        val group = Factory.make().make()\n        val first = group.items[0].item\n        return first.helper(2)\n    }\n    fun runThisChained(): Int {\n        val group = this.make().make()\n        val first = group.items[0].item\n        return first.helper(3)\n    }\n    fun runSuperChained(): Int {\n        val group = super.make().make()\n        val first = group.items[0].item\n        return first.helper(4)\n    }\n    fun runElemThenChained(): Int {\n        val h = Holder()\n        val group = h.make().items[0].inner()\n        return group.helper(5)\n    }\n    fun runDeepChained(): Int {\n        val h = Holder()\n        val group = h.make().make().make()\n        val first = group.items[0].item\n        return first.helper(6)\n    }\n    fun runUnknownChainedFailsClosed(): Int {\n        val h = Holder()\n        val group = h.make().missing()\n        val first = group.items[0].item\n        return first.helper(7)\n    }\n}\n",
    )
    .unwrap();
    fs::write(
        &helper_path,
        "package org.util\n\nclass ImportedItem {\n    fun helper(value: Int): Int = value\n}\n\nclass ImportedInner {\n    val item: ImportedItem = ImportedItem()\n}\n\nclass ImportedGroup {\n    val items: Array<ImportedInner> = arrayOf()\n    fun make(): ImportedGroup = ImportedGroup()\n}\n\nclass ImportedHolder {\n    fun make(): ImportedGroup = ImportedGroup()\n}\n\nobject ImportedFactory {\n    fun make(): ImportedGroup = ImportedGroup()\n}\n",
    )
    .unwrap();
    fs::write(
        dir.join("Imported.kt"),
        "package com.example\n\nimport org.util.ImportedHolder\nimport org.util.ImportedFactory\n\nclass Util2 {\n    fun runImportedBoundChained(): Int {\n        val h = ImportedHolder()\n        val group = h.make().make()\n        val first = group.items[0].item\n        return first.helper(8)\n    }\n    fun runImportedObjectChained(): Int {\n        val group = ImportedFactory.make().make()\n        val first = group.items[0].item\n        return first.helper(9)\n    }\n}\n",
    )
    .unwrap();

    // Chained factory-call initializers pin a `val` local through each
    // intermediate method-call hop before the terminal callee: a locally
    // bound receiver (`h.make().make()`), a named object
    // (`Factory.make().make()`), a `this`-rooted member
    // (`this.make().make()`), a `super`-rooted inherited member
    // (`super.make().make()`), a method terminal after an element-access hop
    // (`h.make().items[0].inner()`), and deeper chains
    // (`h.make().make().make()`). An unknown terminal method
    // (`h.make().missing()`) fails closed, so the six same-package callers in
    // `Util` dispatch on `com::example::Item::helper` and the two imported
    // callers in `Util2` dispatch on `org::util::ImportedItem::helper`.
    let item_path = "com::example::Item::helper";
    let live = trace_symbol_graph(&dir, item_path, TraceDirection::Callers).unwrap();
    assert_eq!(live.symbol.symbol_id, item_path);
    assert_eq!(live.callers.len(), 6);
    for caller in [
        "com::example::Util::runBoundChained",
        "com::example::Util::runObjectChained",
        "com::example::Util::runThisChained",
        "com::example::Util::runSuperChained",
        "com::example::Util::runElemThenChained",
        "com::example::Util::runDeepChained",
    ] {
        assert!(
            live.callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing caller {caller}"
        );
    }
    assert!(
        !live
            .callers
            .iter()
            .any(|candidate| candidate.symbol_id
                == "com::example::Util::runUnknownChainedFailsClosed")
    );

    let imported_item_path = "org::util::ImportedItem::helper";
    let live_imported =
        trace_symbol_graph(&dir, imported_item_path, TraceDirection::Callers).unwrap();
    assert_eq!(live_imported.symbol.symbol_id, imported_item_path);
    assert_eq!(live_imported.callers.len(), 2);
    for caller in [
        "com::example::Util2::runImportedBoundChained",
        "com::example::Util2::runImportedObjectChained",
    ] {
        assert!(
            live_imported
                .callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing caller {caller}"
        );
    }

    rebuild_symbol_index(&dir, &db_path).unwrap();
    let persisted =
        trace_symbol_graph_from_index(&db_path, item_path, TraceDirection::Callers).unwrap();
    assert_eq!(persisted.callers.len(), 6);
    for caller in [
        "com::example::Util::runBoundChained",
        "com::example::Util::runObjectChained",
        "com::example::Util::runThisChained",
        "com::example::Util::runSuperChained",
        "com::example::Util::runElemThenChained",
        "com::example::Util::runDeepChained",
    ] {
        assert!(
            persisted
                .callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing persisted caller {caller}"
        );
    }
    assert!(
        !persisted
            .callers
            .iter()
            .any(|candidate| candidate.symbol_id
                == "com::example::Util::runUnknownChainedFailsClosed")
    );
    let persisted_imported =
        trace_symbol_graph_from_index(&db_path, imported_item_path, TraceDirection::Callers)
            .unwrap();
    assert_eq!(persisted_imported.callers.len(), 2);
    for caller in [
        "com::example::Util2::runImportedBoundChained",
        "com::example::Util2::runImportedObjectChained",
    ] {
        assert!(
            persisted_imported
                .callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing persisted caller {caller}"
        );
    }
}

