#[test]
fn traces_kotlin_scope_function_lambda_branch_local_when_elvis_scope_call_navigation_bindings_in_live_workspace_and_persisted_index()
 {
    let dir = temporary_dir();
    let lib_path = dir.join("Lib.kt");
    let source_path = dir.join("Callers.kt");
    let db_path = dir.join("symbols.db");
    fs::write(
        &lib_path,
        "package com.lib\n\nclass Item {\n    fun helper(value: Int): Int = value\n}\n\nclass Inner {\n    val item: Item = Item()\n}\n\nclass Group {\n    val items: Array<Inner> = arrayOf()\n    fun make(): Group = Group()\n    fun makeAlt(): Group = Group()\n}\n\nclass Holder {\n    fun make(): Group = Group()\n    fun makeAlt(): Group = Group()\n}\n",
    )
    .unwrap();
    fs::write(
        &source_path,
        "package com.example\n\nimport com.lib.Holder\nimport com.lib.Item\n\nclass Util {\n    val h: Holder = Holder()\n    val plainH: Holder = Holder()\n    val nullableH: Holder? = Holder()\n    fun flag(): Boolean = true\n    fun whenNavLetLocal(): Int {\n        val first = h.let { val g1 = when (flag()) { true -> it.make(); else -> it.makeAlt() }; g1.let { g -> g.make() }.items[0].item }\n        return first.helper(1)\n    }\n    fun whenNavRunInnerLocal(): Int {\n        val first = h.let { val g1 = when (flag()) { true -> it.make(); else -> it.makeAlt() }; g1.run { make() }.items[0].item }\n        return first.helper(2)\n    }\n    fun whenNavWithInnerLocal(): Int {\n        val first = h.let { val g1 = when (flag()) { true -> it.make(); else -> it.makeAlt() }; with(g1) { make() }.items[0].item }\n        return first.helper(3)\n    }\n    fun whenNavApplyInnerLocal(): Int {\n        val first = h.let { val g1 = when (flag()) { true -> it.make(); else -> it.makeAlt() }; g1.apply { this }.items[0].item }\n        return first.helper(4)\n    }\n    fun whenNavRunOuterLocal(): Int {\n        val first = h.run { val g1 = when (flag()) { true -> make(); else -> makeAlt() }; g1.let { g -> g.make() }.items[0].item }\n        return first.helper(5)\n    }\n    fun whenNavMemberLocal(): Int {\n        val first = h.let { val g1 = when (flag()) { true -> plainH.make(); else -> plainH.makeAlt() }; g1.let { g -> g.make() }.items[0].item }\n        return first.helper(6)\n    }\n    fun elvisNavLetLocal(): Int {\n        val first = h.let { val g1 = nullableH?.let { it.make() } ?: it.makeAlt(); g1.let { g -> g.make() }.items[0].item }\n        return first.helper(7)\n    }\n    fun elvisNavApplyInnerLocal(): Int {\n        val first = h.let { val g1 = nullableH?.let { it.make() } ?: it.makeAlt(); g1.apply { this }.items[0].item }\n        return first.helper(8)\n    }\n    fun whenNavNoElseFailsClosed(): Int {\n        val first = h.let { val g1 = when (flag()) { true -> it.make() }; g1.let { g -> g.make() }.items[0].item }\n        return first.helper(9)\n    }\n    fun elvisNavUnknownMethodFailsClosed(): Int {\n        val first = h.let { val g1 = nullableH?.let { it.make() } ?: it.makeAlt(); g1.let { g -> g.make() }.missing().items[0].item }\n        return first.helper(10)\n    }\n}",
    )
    .unwrap();

    // A scope-function lambda branch local whose initializer is a `when`
    // expression or an elvis (`?:`) expression, consumed through a
    // scope-call / apply navigation with a trailing member chain such as
    // `g1.let { g -> g.make() }.items[0].item`, binds through the same
    // per-arm expansion rules as an `if` branch local: a `when` with an
    // `else` arm stores the receiver-qualified spellings of every arm, and an
    // elvis local stores both operands (including a safe-call scope-function
    // left operand such as `nullableH?.let { it.make() }`). This covers `let`,
    // `run`, and `with` inner calls, an `apply` navigation, a `when` branch
    // local inside a `run` outer, and an enclosing-member-rooted `when` branch
    // local, all dispatching the terminal member on the imported
    // `com.lib.Item` declaration. A `when` without an `else` arm (whose
    // expression type includes `Unit`) and a chain through an unknown terminal
    // method (`g1.let { g -> g.make() }.missing().items[0].item`) fail closed,
    // so the eight when/elvis scope-call-navigation callers in `Util` dispatch
    // on `com::lib::Item::helper`.
    let item_path = "com::lib::Item::helper";
    let live = trace_symbol_graph(&dir, item_path, TraceDirection::Callers).unwrap();
    assert_eq!(live.symbol.symbol_id, item_path);
    assert_eq!(live.callers.len(), 8);
    for caller in [
        "com::example::Util::whenNavLetLocal",
        "com::example::Util::whenNavRunInnerLocal",
        "com::example::Util::whenNavWithInnerLocal",
        "com::example::Util::whenNavApplyInnerLocal",
        "com::example::Util::whenNavRunOuterLocal",
        "com::example::Util::whenNavMemberLocal",
        "com::example::Util::elvisNavLetLocal",
        "com::example::Util::elvisNavApplyInnerLocal",
    ] {
        assert!(
            live.callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing caller {caller}"
        );
    }
    for caller in [
        "com::example::Util::whenNavNoElseFailsClosed",
        "com::example::Util::elvisNavUnknownMethodFailsClosed",
    ] {
        assert!(
            !live
                .callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "unexpected caller {caller}"
        );
    }

    rebuild_symbol_index(&dir, &db_path).unwrap();
    let persisted =
        trace_symbol_graph_from_index(&db_path, item_path, TraceDirection::Callers).unwrap();
    assert_eq!(persisted.callers.len(), 8);
    for caller in [
        "com::example::Util::whenNavLetLocal",
        "com::example::Util::whenNavRunInnerLocal",
        "com::example::Util::whenNavWithInnerLocal",
        "com::example::Util::whenNavApplyInnerLocal",
        "com::example::Util::whenNavRunOuterLocal",
        "com::example::Util::whenNavMemberLocal",
        "com::example::Util::elvisNavLetLocal",
        "com::example::Util::elvisNavApplyInnerLocal",
    ] {
        assert!(
            persisted
                .callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing persisted caller {caller}"
        );
    }
    for caller in [
        "com::example::Util::whenNavNoElseFailsClosed",
        "com::example::Util::elvisNavUnknownMethodFailsClosed",
    ] {
        assert!(
            !persisted
                .callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "unexpected persisted caller {caller}"
        );
    }
}

#[test]
fn traces_kotlin_scope_function_lambda_branch_local_when_elvis_nested_scope_call_navigation_bindings_in_live_workspace_and_persisted_index()
 {
    let dir = temporary_dir();
    let lib_path = dir.join("Lib.kt");
    let source_path = dir.join("Callers.kt");
    let db_path = dir.join("symbols.db");
    fs::write(
        &lib_path,
        "package com.lib\n\nclass Item {\n    fun helper(value: Int): Int = value\n}\n\nclass Inner {\n    val item: Item = Item()\n}\n\nclass Group {\n    val items: Array<Inner> = arrayOf()\n    fun make(): Group = Group()\n    fun makeAlt(): Group = Group()\n}\n\nclass Holder {\n    fun make(): Group = Group()\n    fun makeAlt(): Group = Group()\n}\n",
    )
    .unwrap();
    fs::write(
        &source_path,
        "package com.example\n\nimport com.lib.Holder\nimport com.lib.Item\n\nclass Util {\n    val h: Holder = Holder()\n    val plainH: Holder = Holder()\n    val nullableH: Holder? = Holder()\n    fun flag(): Boolean = true\n    fun whenNestedNavLetLocal(): Int {\n        val first = h.let { val g1 = when (flag()) { true -> it.make(); else -> it.makeAlt() }; g1.let { g -> val g2 = when (flag()) { true -> g.make(); else -> g.makeAlt() }; g2.let { g3 -> g3.make() }.items[0].item } }\n        return first.helper(1)\n    }\n    fun whenNestedNavElvisInnerLocal(): Int {\n        val first = h.let { val g1 = when (flag()) { true -> it.make(); else -> it.makeAlt() }; g1.let { g -> val g2 = nullableH?.let { it.make() } ?: g.makeAlt(); g2.let { g3 -> g3.make() }.items[0].item } }\n        return first.helper(2)\n    }\n    fun elvisNestedNavLetLocal(): Int {\n        val first = h.let { val g1 = nullableH?.let { it.make() } ?: it.makeAlt(); g1.let { g -> val g2 = when (flag()) { true -> g.make(); else -> g.makeAlt() }; g2.let { g3 -> g3.make() }.items[0].item } }\n        return first.helper(3)\n    }\n    fun whenNestedNavRunOuterLocal(): Int {\n        val first = h.run { val g1 = when (flag()) { true -> make(); else -> makeAlt() }; g1.let { g -> val g2 = when (flag()) { true -> g.make(); else -> g.makeAlt() }; g2.let { g3 -> g3.make() }.items[0].item } }\n        return first.helper(4)\n    }\n    fun whenNestedNavMemberLocal(): Int {\n        val first = h.let { val g1 = when (flag()) { true -> plainH.make(); else -> plainH.makeAlt() }; g1.let { g -> val g2 = when (flag()) { true -> g.make(); else -> g.makeAlt() }; g2.let { g3 -> g3.make() }.items[0].item } }\n        return first.helper(5)\n    }\n    fun elvisNestedNavApplyLocal(): Int {\n        val first = h.let { val g1 = nullableH?.let { it.make() } ?: it.makeAlt(); g1.let { g -> val g2 = when (flag()) { true -> g.make(); else -> g.makeAlt() }; g2.apply { this }.items[0].item } }\n        return first.helper(6)\n    }\n    fun whenNestedNavLocalLocal(): Int {\n        val first = h.let { val g1 = when (flag()) { true -> it.make(); else -> it.makeAlt() }; g1.let { g -> val g2 = when (flag()) { true -> g.make(); else -> g.makeAlt() }; val g3 = g2.let { g3b -> g3b.make() }.items[0].item; g3 } }\n        return first.helper(7)\n    }\n    fun whenNestedNavArmLocal(): Int {\n        val first = h.let { val g1 = when (flag()) { true -> it.make(); else -> it.makeAlt() }; g1.let { g -> val g2 = when (flag()) { true -> g.make(); else -> g.makeAlt() }; if (flag()) g2.let { g3 -> g3.make() }.items[0].item else g2.items[0].item } }\n        return first.helper(8)\n    }\n    fun nullableReceiverNavLocal(): Int {\n        val first = h.let { val g1 = when (flag()) { true -> it.make(); else -> it.makeAlt() }; g1?.let { g -> g.make() }.items[0].item }\n        return first.helper(9)\n    }\n    fun whenNestedNavNoElseFailsClosed(): Int {\n        val first = h.let { val g1 = when (flag()) { true -> it.make(); else -> it.makeAlt() }; g1.let { g -> val g2 = when (flag()) { true -> g.make() }; g2.let { g3 -> g3.make() }.items[0].item } }\n        return first.helper(10)\n    }\n    fun elvisNestedNavUnknownMethodFailsClosed(): Int {\n        val first = h.let { val g1 = nullableH?.let { it.make() } ?: it.makeAlt(); g1.let { g -> val g2 = when (flag()) { true -> g.make(); else -> g.makeAlt() }; g2.let { g3 -> g3.make() }.missing().items[0].item } }\n        return first.helper(11)\n    }\n    fun whenNestedNavChainedLocalFailsClosed(): Int {\n        val first = h.let { val g1 = when (flag()) { true -> it.make(); else -> it.makeAlt() }; g1.let { g -> val g2 = when (flag()) { true -> g.make(); else -> g.makeAlt() }; val g3 = g2; g3.let { g4 -> g4.make() }.items[0].item } }\n        return first.helper(12)\n    }\n    fun whenNestedNavDivergentFailsClosed(): Int {\n        val first = h.let { val g1 = when (flag()) { true -> it.make(); else -> it.makeAlt() }; g1.let { g -> val g2 = when (flag()) { true -> g.make(); else -> Item() }; g2.let { g3 -> g3.make() }.items[0].item } }\n        return first.helper(13)\n    }\n}",
    )
    .unwrap();

    // A scope-function lambda branch local whose initializer is a `when`
    // expression or an elvis (`?:`) expression, with a nested scope-call body
    // that itself declares a nested branch local (`val g2 = when ...` or
    // `val g2 = nullableH?.let { it.make() } ?: ...`) and consumes it through
    // a scope-call / apply navigation with a trailing member chain, expands
    // every branch local once per arm through the same branch rules as an
    // `if` branch local, so the outer initializer binds through the cross
    // product of the outer and nested when/elvis arms. This covers a `when`
    // outer with a `when` or elvis inner, an elvis outer with a `when` inner,
    // a `when` branch local inside a `run` outer, an enclosing-member-rooted
    // `when` branch local, an `apply` navigation on the nested result, a
    // chain stored as a local then consumed (`val g3 = ...; g3`), a branch
    // arm that uses the nested scope-call navigation, and a nullable receiver
    // on the branch local (`g1?.let { g -> g.make() }.items[0].item`), all
    // dispatching the terminal member on the imported `com.lib.Item`
    // declaration. A nested `when` without an `else` arm, a chain through an
    // unknown terminal method, chained bare locals (`val g3 = g2`), and
    // divergent nested branch types fail closed, so the nine when/elvis
    // nested scope-call-navigation callers in `Util` dispatch on
    // `com::lib::Item::helper`.
    let item_path = "com::lib::Item::helper";
    let live = trace_symbol_graph(&dir, item_path, TraceDirection::Callers).unwrap();
    assert_eq!(live.symbol.symbol_id, item_path);
    assert_eq!(live.callers.len(), 9);
    for caller in [
        "com::example::Util::whenNestedNavLetLocal",
        "com::example::Util::whenNestedNavElvisInnerLocal",
        "com::example::Util::elvisNestedNavLetLocal",
        "com::example::Util::whenNestedNavRunOuterLocal",
        "com::example::Util::whenNestedNavMemberLocal",
        "com::example::Util::elvisNestedNavApplyLocal",
        "com::example::Util::whenNestedNavLocalLocal",
        "com::example::Util::whenNestedNavArmLocal",
        "com::example::Util::nullableReceiverNavLocal",
    ] {
        assert!(
            live.callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing caller {caller}"
        );
    }
    for caller in [
        "com::example::Util::whenNestedNavNoElseFailsClosed",
        "com::example::Util::elvisNestedNavUnknownMethodFailsClosed",
        "com::example::Util::whenNestedNavChainedLocalFailsClosed",
        "com::example::Util::whenNestedNavDivergentFailsClosed",
    ] {
        assert!(
            !live
                .callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "unexpected caller {caller}"
        );
    }

    rebuild_symbol_index(&dir, &db_path).unwrap();
    let persisted =
        trace_symbol_graph_from_index(&db_path, item_path, TraceDirection::Callers).unwrap();
    assert_eq!(persisted.callers.len(), 9);
    for caller in [
        "com::example::Util::whenNestedNavLetLocal",
        "com::example::Util::whenNestedNavElvisInnerLocal",
        "com::example::Util::elvisNestedNavLetLocal",
        "com::example::Util::whenNestedNavRunOuterLocal",
        "com::example::Util::whenNestedNavMemberLocal",
        "com::example::Util::elvisNestedNavApplyLocal",
        "com::example::Util::whenNestedNavLocalLocal",
        "com::example::Util::whenNestedNavArmLocal",
        "com::example::Util::nullableReceiverNavLocal",
    ] {
        assert!(
            persisted
                .callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing persisted caller {caller}"
        );
    }
    for caller in [
        "com::example::Util::whenNestedNavNoElseFailsClosed",
        "com::example::Util::elvisNestedNavUnknownMethodFailsClosed",
        "com::example::Util::whenNestedNavChainedLocalFailsClosed",
        "com::example::Util::whenNestedNavDivergentFailsClosed",
    ] {
        assert!(
            !persisted
                .callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "unexpected persisted caller {caller}"
        );
    }
}
#[test]
fn traces_kotlin_scope_function_lambda_branch_local_parenthesized_receiver_scope_call_navigation_bindings_in_live_workspace_and_persisted_index()
 {
    let dir = temporary_dir();
    let lib_path = dir.join("Lib.kt");
    let source_path = dir.join("Callers.kt");
    let db_path = dir.join("symbols.db");
    fs::write(
        &lib_path,
        "package com.lib\n\nclass Item {\n    fun helper(value: Int): Int = value\n}\n\nclass Inner {\n    val item: Item = Item()\n}\n\nclass Group {\n    val items: Array<Inner> = arrayOf()\n    fun make(): Group = Group()\n    fun makeAlt(): Group = Group()\n}\n\nclass Holder {\n    fun make(): Group = Group()\n    fun makeAlt(): Group = Group()\n}\n",
    )
    .unwrap();
    fs::write(
        &source_path,
        "package com.example\n\nimport com.lib.Holder\nimport com.lib.Item\n\nclass Util {\n    val h: Holder = Holder()\n    val plainH: Holder = Holder()\n    fun flag(): Boolean = true\n    fun parenLetLocal(): Int {\n        val first = h.let { val g1 = if (flag()) it.make() else it.makeAlt(); (g1).let { g -> g.make() }.items[0].item }\n        return first.helper(1)\n    }\n    fun parenRunInnerLocal(): Int {\n        val first = h.let { val g1 = if (flag()) it.make() else it.makeAlt(); (g1).run { make() }.items[0].item }\n        return first.helper(2)\n    }\n    fun parenWithLocal(): Int {\n        val first = h.let { val g1 = if (flag()) it.make() else it.makeAlt(); with((g1)) { make() }.items[0].item }\n        return first.helper(3)\n    }\n    fun parenApplyLocal(): Int {\n        val first = h.let { val g1 = if (flag()) it.make() else it.makeAlt(); (g1).apply { this }.items[0].item }\n        return first.helper(4)\n    }\n    fun parenResultLocal(): Int {\n        val first = h.let { val g1 = if (flag()) it.make() else it.makeAlt(); (g1.let { g -> g.make() }).items[0].item }\n        return first.helper(5)\n    }\n    fun parenNestedLocal(): Int {\n        val first = h.let { val g1 = if (flag()) it.make() else it.makeAlt(); ((g1).let { g -> g.make() }).items[0].item }\n        return first.helper(6)\n    }\n    fun parenRunOuterLocal(): Int {\n        val first = h.run { val g1 = if (flag()) make() else makeAlt(); (g1).let { g -> g.make() }.items[0].item }\n        return first.helper(7)\n    }\n    fun parenMemberLocal(): Int {\n        val first = h.let { val g1 = if (flag()) plainH.make() else plainH.makeAlt(); (g1).let { g -> g.make() }.items[0].item }\n        return first.helper(8)\n    }\n    fun parenChainReceiverLocal(): Int {\n        val first = h.let { val g1 = if (flag()) it.make() else it.makeAlt(); (g1.make()).let { g -> g.make() }.items[0].item }\n        return first.helper(9)\n    }\n    fun parenUnknownMethodFailsClosed(): Int {\n        val first = h.let { val g1 = if (flag()) it.make() else it.makeAlt(); (g1).let { g -> g.make() }.missing().items[0].item }\n        return first.helper(10)\n    }\n    fun parenChainedLocalFailsClosed(): Int {\n        val first = h.let { val g1 = if (flag()) it.make() else it.makeAlt(); val g2 = g1; (g2).let { g -> g.make() }.items[0].item }\n        return first.helper(11)\n    }\n    fun parenNoElseFailsClosed(): Int {\n        val first = h.let { val g1 = if (flag()) it.make(); (g1).let { g -> g.make() }.items[0].item }\n        return first.helper(12)\n    }\n    fun parenDivergentFailsClosed(): Int {\n        val first = h.let { val g1 = if (flag()) it.make() else Item(); (g1).let { g -> g.make() }.items[0].item }\n        return first.helper(13)\n    }\n}",
    )
    .unwrap();

    // A scope-function lambda branch local consumed through a scope-call /
    // apply navigation whose receiver or scope-call result is parenthesized,
    // such as `(g1).let { g -> g.make() }.items[0].item`,
    // `with((g1)) { make() }.items[0].item`,
    // `(g1.let { g -> g.make() }).items[0].item`, or
    // `((g1).let { g -> g.make() }).items[0].item`, unwraps the parentheses
    // before the branch-local root lookup and per-arm expansion, so the outer
    // initializer binds through the same branch rules as the unparenthesized
    // form. This covers `let`, `run`, and `with` inner calls with a trailing
    // member chain, an `apply` navigation, a `with` receiver that is itself
    // parenthesized, a parenthesized scope-call result with a trailing chain,
    // nested parentheses around both the receiver and the call, a branch
    // local inside a `run` outer, an enclosing-member-rooted branch local,
    // and a parenthesized receiver chain rooted on the branch local
    // (`(g1.make()).let { g -> g.make() }.items[0].item`), all dispatching
    // the terminal member on the imported `com.lib.Item` declaration. A chain
    // through an unknown terminal method, chained bare locals (`val g2 = g1`),
    // a branch local without an `else` arm, and divergent branch types fail
    // closed, so the nine parenthesized scope-call-navigation callers in
    // `Util` dispatch on `com::lib::Item::helper`.
    let item_path = "com::lib::Item::helper";
    let live = trace_symbol_graph(&dir, item_path, TraceDirection::Callers).unwrap();
    assert_eq!(live.symbol.symbol_id, item_path);
    assert_eq!(live.callers.len(), 9);
    for caller in [
        "com::example::Util::parenLetLocal",
        "com::example::Util::parenRunInnerLocal",
        "com::example::Util::parenWithLocal",
        "com::example::Util::parenApplyLocal",
        "com::example::Util::parenResultLocal",
        "com::example::Util::parenNestedLocal",
        "com::example::Util::parenRunOuterLocal",
        "com::example::Util::parenMemberLocal",
        "com::example::Util::parenChainReceiverLocal",
    ] {
        assert!(
            live.callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing caller {caller}"
        );
    }
    for caller in [
        "com::example::Util::parenUnknownMethodFailsClosed",
        "com::example::Util::parenChainedLocalFailsClosed",
        "com::example::Util::parenNoElseFailsClosed",
        "com::example::Util::parenDivergentFailsClosed",
    ] {
        assert!(
            !live
                .callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "unexpected caller {caller}"
        );
    }

    rebuild_symbol_index(&dir, &db_path).unwrap();
    let persisted =
        trace_symbol_graph_from_index(&db_path, item_path, TraceDirection::Callers).unwrap();
    assert_eq!(persisted.callers.len(), 9);
    for caller in [
        "com::example::Util::parenLetLocal",
        "com::example::Util::parenRunInnerLocal",
        "com::example::Util::parenWithLocal",
        "com::example::Util::parenApplyLocal",
        "com::example::Util::parenResultLocal",
        "com::example::Util::parenNestedLocal",
        "com::example::Util::parenRunOuterLocal",
        "com::example::Util::parenMemberLocal",
        "com::example::Util::parenChainReceiverLocal",
    ] {
        assert!(
            persisted
                .callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing persisted caller {caller}"
        );
    }
    for caller in [
        "com::example::Util::parenUnknownMethodFailsClosed",
        "com::example::Util::parenChainedLocalFailsClosed",
        "com::example::Util::parenNoElseFailsClosed",
        "com::example::Util::parenDivergentFailsClosed",
    ] {
        assert!(
            !persisted
                .callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "unexpected persisted caller {caller}"
        );
    }
}
#[test]
fn traces_csharp_var_multidimensional_array_element_access_receiver_calls_in_live_workspace_and_persisted_index()
 {
    let dir = temporary_dir();
    let source_path = dir.join("Types.cs");
    let db_path = dir.join("symbols.db");
    fs::write(
        &source_path,
        "namespace Demo;
class Helper {
    public int helper(int value) => value;
}
class Util {
    public static Helper[,] makeGrid() => new Helper[2, 2];
    public static Helper[,,] makeCube() => new Helper[2, 2, 2];
    public static Helper[][] makeJagged() => new Helper[2][];
}
class Caller {
    Helper[,] fieldGrid = new Helper[2, 2];
    Helper[,] makeLocalGrid() => new Helper[2, 2];
    int fromField() {
        var first = fieldGrid[0, 0];
        return first.helper(1);
    }
    int fromFactory() {
        var first = Util.makeGrid()[0, 0];
        return first.helper(2);
    }
    int fromCube() {
        var first = Util.makeCube()[0, 0, 0];
        return first.helper(3);
    }
    int fromLocal() {
        var first = this.makeLocalGrid()[0, 1];
        return first.helper(4);
    }
    int fromBound(Helper[,] boundGrid) {
        var first = boundGrid[1, 0];
        return first.helper(5);
    }
    int jaggedFailsClosed() {
        var first = Util.makeJagged()[0];
        return first.helper(6);
    }
}
",
    )
    .unwrap();

    // A `var` local bound from a multi-dimensional array element access such
    // as `var first = fieldGrid[0, 0]` or `var first = Util.makeGrid()[0, 0]`
    // dispatches on the array's element component type: the element component
    // type of `Helper[,]` (and `Helper[,,]`) is the same base type as a
    // single-level array, so field bases, qualified and `this`-rooted factory
    // bases, and bound-receiver bases all resolve `first.helper(...)` to the
    // imported `Demo::Helper` declaration. A single element access on a
    // jagged array (`var first = Util.makeJagged()[0]`) still fails closed
    // because stripping one layer from `Helper[][]` leaves the nested
    // `Helper[]` component, which is not a resolvable type, so the five
    // multi-dimensional element-access callers in `Caller` dispatch on
    // `Demo::Helper::helper`.
    let helper_symbol = "Demo::Helper::helper";
    let live = trace_symbol_graph(&dir, helper_symbol, TraceDirection::Callers).unwrap();
    assert_eq!(live.symbol.symbol_id, helper_symbol);
    assert_eq!(live.callers.len(), 5);
    for caller in [
        "Demo::Caller::fromField",
        "Demo::Caller::fromFactory",
        "Demo::Caller::fromCube",
        "Demo::Caller::fromLocal",
        "Demo::Caller::fromBound",
    ] {
        assert!(
            live.callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing caller {caller}"
        );
    }
    assert!(
        !live
            .callers
            .iter()
            .any(|candidate| candidate.symbol_id == "Demo::Caller::jaggedFailsClosed"),
        "unexpected jagged caller"
    );

    rebuild_symbol_index(&dir, &db_path).unwrap();
    let persisted =
        trace_symbol_graph_from_index(&db_path, helper_symbol, TraceDirection::Callers).unwrap();
    assert_eq!(persisted.symbol.symbol_id, helper_symbol);
    assert_eq!(persisted.callers.len(), 5);
    for caller in [
        "Demo::Caller::fromField",
        "Demo::Caller::fromFactory",
        "Demo::Caller::fromCube",
        "Demo::Caller::fromLocal",
        "Demo::Caller::fromBound",
    ] {
        assert!(
            persisted
                .callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing persisted caller {caller}"
        );
    }
    assert!(
        !persisted
            .callers
            .iter()
            .any(|candidate| candidate.symbol_id == "Demo::Caller::jaggedFailsClosed"),
        "unexpected persisted jagged caller"
    );
}

